(window.PSAC_DEMO_DECKS = window.PSAC_DEMO_DECKS || {})[2] = {"grade":2,"packs":{"grade2-english":{"g2eng-listening":[{"id":"g2eng-lis-056","q":"Instruction: \"Put a circle around the SMALLEST number: 7, 3, 9, 5.\" Which number should you circle?","opts":["5","7","9","3"],"a":"3","hint":"Look at all four numbers. Which one is the least?","exp":"You should circle <b>3</b> — it is the smallest number. 3 < 5 < 7 < 9."},{"id":"g2eng-lis-014","q":"Which pair starts with the SAME sound but DIFFERENT letters?","opts":["dog and door","cake and kite","pig and pen","moon and mop"],"a":"cake and kite","hint":"Say the first sound of each pair aloud, then look at the first letter of each word.","exp":"<b>Cake and kite</b> both start with the /k/ sound, but one is spelt with a <b>c</b> and the other with a <b>k</b>. The other pairs share their first sound <i>and</i> their first letter: p-p, m-m, d-d."},{"id":"g2eng-lis-058","q":"Instruction: \"Draw a line under the word that names a COLOUR.\" Which word should you underline?","opts":["book","blue","run","happy"],"a":"blue","hint":"Colours are words like red, green, yellow. Which word in the list is a colour?","exp":"You should underline <b>blue</b> — it is a colour. Run is an action, happy is a feeling, and book is a thing."},{"id":"g2eng-lis-008","q":"Which word starts with the same sound as \"phone\"?","opts":["van","fish","pen","bee"],"a":"fish","hint":"\"Phone\" starts with the /f/ sound even though it is spelled with \"ph\". Which word starts with /f/?","exp":"<b>Fish</b> starts with the /f/ sound, just like phone. The letters \"ph\" and \"f\" both make the same /f/ sound!"},{"id":"g2eng-lis-060","q":"Instruction: \"Cross out the word that is spelled INCORRECTLY.\" Which word should you cross out?","opts":["happy","frend","sunny","friend"],"a":"frend","hint":"One of these words has a spelling mistake. Say each word and check the letters.","exp":"You should cross out <b>frend</b> — it is spelled incorrectly. The correct spelling is <b>friend</b>."}],"g2eng-speaking":[{"id":"g2eng-spk-010","q":"Which sentence retells the MIDDLE part of this story: \"The rabbit was hungry. It ate a carrot. Then it hopped away.\"","opts":["The rabbit was hungry.","Then it hopped away.","The rabbit slept.","It ate a carrot."],"a":"It ate a carrot.","hint":"The middle event comes between the beginning (hungry rabbit) and the end (hopped away).","exp":"\"<b>It ate a carrot.</b>\" is the middle event — it comes after the rabbit was hungry and before it hopped away."},{"id":"g2eng-spk-024","q":"When retelling, what does \"the ending\" tell your listener?","opts":["What the character looks like","When the story started","How the story finished","Where the story happened"],"a":"How the story finished","hint":"The ending is the last part — it tells your listener how everything worked out.","exp":"The ending tells your listener <b>how the story finished</b> — did the problem get solved? Was the character happy or sad at the end?"},{"id":"g2eng-spk-002","q":"\"First, the girl found a kitten. Next, she gave it some milk. Then, she made it a bed. Last, the kitten fell asleep.\" What happened AFTER she gave it milk?","opts":["The kitten fell asleep","She made it a bed","She found the kitten","She called her mum"],"a":"She made it a bed","hint":"The order is: found → gave milk → ??? → fell asleep. What comes after giving milk?","exp":"After giving the kitten milk, <b>she made it a bed</b>. The order words First, Next, Then and Last help you follow the story."},{"id":"g2eng-spk-028","q":"When describing a picture, which question should you ask FIRST?","opts":["What is the date?","What do I smell?","How old is the picture?","What can I see?"],"a":"What can I see?","hint":"Describing a picture starts with looking carefully at everything in it.","exp":"We always start by asking \"<b>What can I see?</b>\" — we name everything we observe: the people, animals, objects, colours and what is happening."},{"id":"g2eng-spk-004","q":"A story says: \"The children played in the garden. They heard the rain start. They ran inside.\" What happened LAST?","opts":["They heard the rain.","They ran inside.","They got wet.","They played in the garden."],"a":"They ran inside.","hint":"The events happen in order in the story. Which event is at the end?","exp":"The children <b>ran inside</b> last — after they heard the rain. We always retell events in the order they happened."}],"g2eng-reading":[{"id":"g2eng-rdr-001","q":"Which word is made by blending the sounds /sh/ + /i/ + /p/?","opts":["slip","ship","chip","skip"],"a":"ship","hint":"Put the sounds together: /sh/-/i/-/p/. Say them quickly one after another.","exp":"<b>Ship</b> is the word made by blending /sh/ + /i/ + /p/. We read by blending the sounds together quickly: sh-i-p = ship!"},{"id":"g2eng-rdr-006","q":"What sound does \"wh\" make in the word \"whale\"?","opts":["/ th/","/w/","/ ch/","/ sh/"],"a":"/w/","hint":"\"wh\" makes the /w/ sound in most words. Say \"whale\" — what is the first sound?","exp":"\"wh\" in <b>whale</b> makes the /w/ sound — /w/-ale. Other \"wh\" words: what, when, where, which, wheel."},{"id":"g2eng-rdr-019","q":"Which word ends with the \"ng\" digraph?","opts":["sing","sill","silk","sink"],"a":"sing","hint":"\"ng\" at the end makes one sound — like the humming sound at the end of \"ring\".","exp":"<b>Sing</b> ends with the \"ng\" digraph — si-ng. Ring, king, long and song also end with \"ng\"."},{"id":"g2eng-rdr-066","q":"\"Penguins live in very cold places. They cannot fly but they are excellent swimmers. They use their wings like flippers to swim fast.\" Where do penguins live?","opts":["In tropical forests","In very cold places","In hot deserts","In Mauritius"],"a":"In very cold places","hint":"The first sentence tells you where penguins live.","exp":"Penguins live <b>in very cold places</b> — the first sentence says so clearly. Antarctica is the coldest place on Earth and many penguins live there!"},{"id":"g2eng-rdr-004","q":"Apply the silent-e rule. Which word has a LONG vowel sound?","opts":["cake","cab","cap","cat"],"a":"cake","hint":"The magic-e rule: if a word ends in e, the vowel before it says its name (long sound).","exp":"<b>Cake</b> has a long /ā/ vowel sound. The \"e\" at the end is silent but makes the \"a\" say its name. Cap, cat and cab all have a short /a/ sound."}]},"grade2-french":{"g2fr-comprehension-orale":[{"id":"g2fr-co-021","q":"Écoute : « La tortue marche lentement sur la plage. Elle cherche la mer. » Comment marche la tortue ?","opts":["En courant","Lentement","Vite","En sautant"],"a":"Lentement","hint":"Un adverbe dans le texte dit comment elle marche. (An adverb in the text says how she walks.)","exp":"La tortue marche <b>lentement</b>. (The turtle walks slowly.)"},{"id":"g2fr-co-051","q":"Dans la phrase « Le chien est rapide », que veut dire « rapide » ?","opts":["Qui est triste","Qui est beau","Qui est grand","Qui va vite"],"a":"Qui va vite","hint":"Un animal rapide se déplace sans s'arrêter longtemps. (A fast animal moves without stopping for long.)","exp":"<b>Rapide</b> = qui va vite. Un guépard est rapide. (Rapide = fast. A cheetah is fast.)"},{"id":"g2fr-co-059","q":"Dans la phrase « Il est interdit de courir ici », que veut dire « interdit » ?","opts":["Amusant","Obligatoire","Pas permis","Facile"],"a":"Pas permis","hint":"Un panneau rouge dit souvent quelque chose d'interdit. (A red sign often says something is forbidden.)","exp":"<b>Interdit</b> = pas permis, ce qu'on ne doit pas faire. (Interdit = not allowed, what one must not do.)"},{"id":"g2fr-co-036","q":"Écoute : « D'abord, Sonia peint la toile. Ensuite, elle la montre à la maîtresse. Enfin, elle accroche le tableau. » Que fait Sonia en dernier ?","opts":["Elle accroche le tableau","Elle montre à la maîtresse","Elle peint la toile","Elle nettoie le pinceau"],"a":"Elle accroche le tableau","hint":"La dernière action est indiquée par « enfin ». (The last action is signalled by \"enfin\".)","exp":"<b>Enfin</b>, Sonia accroche le tableau. (Finally, Sonia hangs up the painting.)"},{"id":"g2fr-co-014","q":"Écoute : « Ravi dessine une fleur jaune dans son cahier. Il aime l'art. » Que fait Ravi ?","opts":["Il chante une chanson","Il lit un livre","Il mange un fruit","Il dessine une fleur"],"a":"Il dessine une fleur","hint":"Quelle activité fait Ravi ? (What activity is Ravi doing?)","exp":"Ravi <b>dessine</b> une fleur jaune. Il aime l'art. (Ravi draws a yellow flower. He likes art.)"}],"g2fr-expression-orale":[{"id":"g2fr-eo-058","q":"Lis : « Où habites-tu ? » Quelle réponse complète convient ?","opts":["J'habite à Port-Louis.","À l'école.","Port-Louis.","Oui."],"a":"J'habite à Port-Louis.","hint":"La réponse doit reprendre le verbe de la question. (The answer should reuse the verb from the question.)","exp":"<b>J'habite à Port-Louis</b> est une réponse complète avec sujet + verbe + lieu. (I live in Port-Louis — a complete answer with subject + verb + place.)"},{"id":"g2fr-eo-012","q":"Regarde une image : un vieux monsieur lit un journal sur un banc. Qui est sur le banc ?","opts":["Un chien","Une dame","Un vieux monsieur","Un enfant"],"a":"Un vieux monsieur","hint":"Qui est le personnage dans l'image ? (Who is the character in the picture?)","exp":"<b>Un vieux monsieur</b> est assis sur le banc et lit un journal. (An old man sits on the bench reading a newspaper.)"},{"id":"g2fr-eo-001","q":"Regarde une image : un enfant joue avec un ballon rouge. Quelle phrase décrit le mieux l'image ?","opts":["Un enfant joue avec un ballon rouge.","Un chat dort sur le tapis.","Un oiseau vole dans le ciel.","Un enfant mange une pomme."],"a":"Un enfant joue avec un ballon rouge.","hint":"Dis ce que tu vois : qui fait quoi avec quel objet ? (Say what you see: who does what with which object?)","exp":"On décrit l'image en disant <b>qui</b> (un enfant), <b>quoi</b> (joue), et <b>avec quoi</b> (un ballon rouge). (We describe the picture by saying who, does what, and with what.)"},{"id":"g2fr-eo-049","q":"Lis : « Sara est triste. Elle a perdu sa poupée. Sa maman l'aide à chercher. Enfin, ils la trouvent sous le lit. » Comment se termine l'histoire ?","opts":["Sara pleure encore","La poupée est cassée","La maman achète une nouvelle poupée","Ils trouvent la poupée sous le lit"],"a":"Ils trouvent la poupée sous le lit","hint":"La fin résout le problème. (The ending solves the problem.)","exp":"<b>Enfin</b>, ils trouvent la poupée sous le lit — le problème est résolu. (Finally, they find the doll under the bed — the problem is solved.)"},{"id":"g2fr-eo-007","q":"Regarde une image : des enfants mangent de la glace sur la plage. Où sont-ils ?","opts":["Dans une école","Dans une forêt","Dans un parc","Sur la plage"],"a":"Sur la plage","hint":"Quel endroit vois-tu dans l'arrière-plan ? (What place do you see in the background?)","exp":"Les enfants sont <b>sur la plage</b>. Nommer le lieu aide à bien décrire l'image. (The children are on the beach. Naming the place helps describe the picture well.)"}],"g2fr-lecture":[{"id":"g2fr-lec-003","q":"Combien de syllabes a le mot « ba-na-ne » ?","opts":["4","1","3","2"],"a":"3","hint":"ba - na - ne. (ba - na - ne.)","exp":"« ba-na-ne » a <b>3 syllabes</b>. (Banane has 3 syllables.)"},{"id":"g2fr-lec-033","q":"Lis : « Les étoiles brillent la nuit. La lune est ronde. » À quel moment brillent les étoiles ?","opts":["Le soir seulement","L'après-midi","Le matin","La nuit"],"a":"La nuit","hint":"Quand les étoiles sont-elles visibles ? (When are stars visible?)","exp":"Les étoiles brillent <b>la nuit</b>. (The stars shine at night.)"},{"id":"g2fr-lec-015","q":"Quelle lettre manque dans « so-_eil » pour faire « soleil » ?","opts":["l","m","r","n"],"a":"l","hint":"so + l + eil = soleil. (so + l + eil = soleil.)","exp":"so + <b>l</b> + eil = <b>soleil</b>. (so + l + eil = soleil — sun.)"},{"id":"g2fr-lec-045","q":"Lis : « Les enfants plantent des graines au printemps. En été, les fleurs éclosent. » Quand les fleurs éclosent-elles ?","opts":["En été","Au printemps","En automne","En hiver"],"a":"En été","hint":"La saison est dans la deuxième phrase. (The season is in the second sentence.)","exp":"Les fleurs éclosent <b>en été</b>. (The flowers bloom in summer.)"},{"id":"g2fr-lec-067","q":"Un texte de conte commence souvent par :","opts":["Ingrédients :","Le saviez-vous ?","Il était une fois...","Cher ami,"],"a":"Il était une fois...","hint":"Cette expression introduit les histoires imaginaires pour enfants. (This expression introduces imaginary stories for children.)","exp":"<b>Il était une fois...</b> est la formule classique du début d'un conte. (\"Il était une fois...\" is the classic opening formula of a fairy tale.)"}]},"grade2-health":{"g2he-hygiene":[{"id":"g2he-hyg-038","q":"Why should we cover cuts or sores before going to school?","opts":["Only if a teacher asks","To look tidy only","To keep germs out","Cuts never need covers"],"a":"To keep germs out","hint":"","exp":"Covering wounds with a clean plaster or bandage <b>protects the wound from germs</b> and prevents blood or fluid from spreading to others."},{"id":"g2he-hyg-056","q":"Which action helps PREVENT the spread of germs at school?","opts":["Playing in mud all day","Never washing our hands","Sharing pencils with all","Washing hands regularly"],"a":"Washing hands regularly","hint":"","exp":"The key actions to prevent germs spreading in school are <b>hand washing, not sharing food/drinks and covering coughs</b>."},{"id":"g2he-hyg-026","q":"Which of these habits helps PREVENT illness from spreading?","opts":["Going to school very ill","Covering our coughs","Sharing drinks when ill","Coughing over others"],"a":"Covering our coughs","hint":"Think about what stops germs moving from person to person.","exp":"<b>Washing hands, covering coughs and not sharing utensils</b> all prevent germs from spreading from person to person."},{"id":"g2he-hyg-019","q":"When should you change your toothbrush?","opts":["Every ten years","Never in your life","Every three months","Only when it breaks"],"a":"Every three months","hint":"Worn bristles do not clean teeth as well.","exp":"Replace your toothbrush <b>every 3 months</b> or sooner if the bristles are splayed — worn bristles cannot clean teeth effectively."},{"id":"g2he-hyg-005","q":"Raj has not bathed in three days. What is MOST LIKELY to happen?","opts":["He will become stronger","His body will smell","He will grow taller","Nothing will happen"],"a":"His body will smell","hint":"Think about what dirt and sweat do over time.","exp":"Without bathing, <b>bacteria build up on the skin</b> and the body develops an unpleasant smell. Daily bathing is important."}],"g2he-nutrition":[{"id":"g2he-nut-006","q":"Which food group does milk belong to?","opts":["Dairy foods","Fruits","Protein foods","Starchy foods"],"a":"Dairy foods","hint":"Milk comes from cows — think about what it does for bones.","exp":"Milk belongs to the <b>dairy foods</b> group. It provides calcium for strong bones and teeth."},{"id":"g2he-nut-048","q":"Which approach to mealtimes is healthiest?","opts":["Eating only when hungry","Sweets instead of meals","Regular meals every day","One large meal a day"],"a":"Regular meals every day","hint":"","exp":"<b>Regular meals at consistent times</b> keep blood sugar stable, support growth and provide steady energy for learning and play."},{"id":"g2he-nut-051","q":"Why do we keep cooked food covered?","opts":["Only to keep it warm","There is no reason","To keep flies off it","Only to look nicer"],"a":"To keep flies off it","hint":"","exp":"Flies carry germs and contaminate food. <b>Keeping food covered</b> protects it from flies and other sources of contamination."},{"id":"g2he-nut-002","q":"Which food group helps our muscles and body grow?","opts":["Sugary drinks","Protein foods","Crisps and chips","Oil and butter"],"a":"Protein foods","hint":"These foods help our body build and repair itself.","exp":"<b>Protein foods</b> (meat, fish, eggs, beans) provide the building blocks our body needs for growth and repair."},{"id":"g2he-nut-038","q":"Sophie wants to build strong muscles. Which food should she eat more of?","opts":["Fizzy drinks and cake","Butter and cooking oil","Sugar and sweets only","Chicken, eggs and beans"],"a":"Chicken, eggs and beans","hint":"","exp":"<b>Protein foods</b> (chicken, eggs, beans) are the building blocks of muscles. Sophie needs more protein to help her muscles grow and repair."}],"g2he-safety":[{"id":"g2he-saf-017","q":"Should you look at your phone while crossing the road?","opts":["No, watch the traffic","Yes, if it is important","Yes, if you walk fast","Yes, if almost across"],"a":"No, watch the traffic","hint":"Distracted walking causes accidents.","exp":"<b>No</b> — using your phone while crossing is very dangerous. You need your full attention on traffic at all times."},{"id":"g2he-saf-011","q":"Before crossing the road, you should:","opts":["Look only one way","Look at your phone","Run across without looking","Stop, look and listen"],"a":"Stop, look and listen","hint":"The Green Cross Code keeps us safe.","exp":"Always <b>Stop → Look left → Look right → Look left again → Cross when safe</b>. Look left twice as vehicles on the left are closest first."},{"id":"g2he-saf-003","q":"What should you do if you find a bottle of bleach or cleaning fluid at home?","opts":["Open it to see inside","Smell it to see what it is","Leave it and tell an adult","Share it with a friend"],"a":"Leave it and tell an adult","hint":"Cleaning products are chemicals and can be dangerous.","exp":"<b>Leave it and tell an adult</b>. Cleaning products like bleach are dangerous chemicals that can burn skin and eyes."},{"id":"g2he-saf-012","q":"Where is the safest place to cross the road?","opts":["Anywhere while running","Between parked cars","At a marked crossing","Behind a lorry or bus"],"a":"At a marked crossing","hint":"Marked crossings are where drivers expect people.","exp":"Always use a <b>marked pedestrian crossing</b> where drivers expect people and it is safer to cross."},{"id":"g2he-saf-045","q":"Why is it dangerous to play ball games near a busy road?","opts":["Roads are too hard to play on","The ball can roll onto it","There is no danger at all","Balls are not allowed there"],"a":"The ball can roll onto it","hint":"","exp":"When a ball rolls onto a road, a child may chase it without checking for traffic — running into the path of a vehicle. <b>Always play away from roads.</b>"}]},"grade2-maths":{"g2mth-numbers":[{"id":"g2mth-num-019","q":"What is the value of 7 in the number 76?","opts":["7","6","60","70"],"a":"70","hint":"7 is in the tens place.","exp":"The digit 7 is in the tens place in 76, so its value is <b>70</b>."},{"id":"g2mth-num-005","q":"How many ones are in the number 47?","opts":["7","4","47","70"],"a":"7","hint":"Look at the last digit — that is the ones place.","exp":"In 47, the digit in the <b>ones place</b> is <b>7</b>."},{"id":"g2mth-num-050","q":"Which of these numbers is even?","opts":["80","83","89","87"],"a":"80","hint":"Even numbers end in 0, 2, 4, 6, or 8.","exp":"80 ends in 0, so <b>80</b> is even."},{"id":"g2mth-num-013","q":"Dev has 6 ten-rupee notes and 3 one-rupee coins. How much money does he have?","opts":["Rs63","Rs360","Rs603","Rs36"],"a":"Rs63","hint":"6 tens = 60, plus 3 ones = 3.","exp":"6 ten-rupee notes = Rs60, and 3 one-rupee coins = Rs3. Total = <b>Rs63</b>."},{"id":"g2mth-num-016","q":"Mia counts 5 boxes of 10 crayons and 8 single crayons. How many crayons in total?","opts":["508","85","58","580"],"a":"58","hint":"5 boxes of 10 = 50. Plus 8 singles.","exp":"5 × 10 = 50, plus 8 = <b>58</b> crayons."}],"g2mth-addition":[{"id":"g2mth-add-037","q":"55 + 39 = ? (regrouping needed)","opts":["95","74","94","84"],"a":"94","hint":"Ones: 5+9=14 (write 4, carry 1). Tens: 5+3+1=9.","exp":"55+39: ones 5+9=14 (write 4, carry 1); tens 5+3+1=9. Answer = <b>94</b>."},{"id":"g2mth-add-033","q":"36 + 56 = ? (regrouping needed)","opts":["72","92","82","93"],"a":"92","hint":"Ones: 6+6=12 (write 2, carry 1). Tens: 3+5+1=9.","exp":"36+56: ones 6+6=12 (write 2, carry 1); tens 3+5+1=9. Answer = <b>92</b>."},{"id":"g2mth-add-052","q":"Priya has Rs26 and her brother gives her Rs15. How much does she have now?","opts":["Rs31","Rs51","Rs41","Rs40"],"a":"Rs41","hint":"26 + 15. Ones: 6+5=11 (write 1, carry 1). Tens: 2+1+1=4.","exp":"26 + 15 = <b>Rs41</b>."},{"id":"g2mth-add-025","q":"65 + 28 = ? (regrouping needed)","opts":["83","93","94","73"],"a":"93","hint":"Ones: 5+8=13 (write 3, carry 1). Tens: 6+2+1=9.","exp":"65+28: ones 5+8=13 (write 3, carry 1); tens 6+2+1=9. Answer = <b>93</b>."},{"id":"g2mth-add-015","q":"What is 37 + 30?","opts":["67","77","47","38"],"a":"67","hint":"37 + 30: add 3 to the tens digit of 37.","exp":"37 + 30 = <b>67</b>. The tens go from 3 to 6."}],"g2mth-subtraction":[{"id":"g2mth-sub-026","q":"74 − 39 = ? (regrouping needed)","opts":["35","45","25","36"],"a":"35","hint":"Ones: 4−9 (regroup). 14−9=5. Tens: 7−1−3=3.","exp":"74 − 39: regroup (14−9=5, 6−3=3). Answer = <b>35</b>."},{"id":"g2mth-sub-034","q":"60 − 38 = ? (regrouping needed)","opts":["22","21","12","32"],"a":"22","hint":"Ones: 0−8 (regroup). 10−8=2. Tens: 6−1−3=2.","exp":"60 − 38: regroup (10−8=2, 5−3=2). Answer = <b>22</b>."},{"id":"g2mth-sub-045","q":"A bag had 52 mangoes. 25 were eaten. How many remain?","opts":["17","37","27","26"],"a":"27","hint":"52 − 25. Ones: 2−5 (regroup). 12−5=7. Tens: 5−1−2=2.","exp":"52 − 25 = <b>27</b> mangoes."},{"id":"g2mth-sub-028","q":"91 − 67 = ? (regrouping needed)","opts":["24","23","34","14"],"a":"24","hint":"Ones: 1−7 (regroup). 11−7=4. Tens: 9−1−6=2.","exp":"91 − 67: regroup (11−7=4, 8−6=2). Answer = <b>24</b>."},{"id":"g2mth-sub-015","q":"Rani had 50 sweets. She gave 20 to her friends. How many are left?","opts":["20","10","30","40"],"a":"30","hint":"50 − 20 = ?","exp":"50 − 20 = <b>30</b> sweets left."}]}}};
